 --radius-4xl: calc(var(--radius) * 2.6);
}

:root {
 --background: oklch(0.07 0 0);
 --foreground: oklch(0.97 0 0);
 --card: oklch(0.1 0 0);
 --card-foreground: oklch(0.97 0 0);
 --popover: oklch(0.1 0 0);
 --popover-foreground: oklch(0.97 0 0);
 --primary: oklch(0.97 0 0);
 --primary-foreground: oklch(0.07 0 0);
 --secondary: oklch(0.15 0 0);
 --secondary-foreground: oklch(0.97 0 0);
 --muted: oklch(0.15 0 0);
 --muted-foreground: oklch(0.55 0 0);
 --accent: oklch(0.15 0 0);
 --accent-foreground: oklch(0.97 0 0);
 --destructive: oklch(0.704 0.191 22.216);
 --border: oklch(1 0 0 / 8%);
 --input: oklch(1 0 0 / 10%);
 --ring: oklch(0.45 0 0);
 --chart-1: oklch(0.65 0.18 264);
 --chart-2: oklch(0.6 0.15 150);
 --chart-3: oklch(0.6 0.18 30);
 --chart-4: oklch(0.6 0.18 310);
 --chart-5: oklch(0.6 0.18 190);
 --radius: 0.625rem;
 --sidebar: oklch(0.1 0 0);
 --sidebar-foreground: oklch(0.97 0 0);
 --sidebar-primary: oklch(0.488 0.243 264.376);
 --sidebar-primary-foreground: oklch(0.97 0 0);
 --sidebar-accent: oklch(0.15 0 0);
 --sidebar-accent-foreground: oklch(0.97 0 0);
 --sidebar-border: oklch(1 0 0 / 8%);
 --sidebar-ring: oklch(0.45 0 0);
 --duration-exit: 150ms;
 --duration-enter: 210ms;
 --duration-move: 400ms;
}

@keyframes fade {
 from { filter: blur(3px); opacity: 0; }
 to { filter: blur(0); opacity: 1; }
}

@keyframes slide {
 from { translate: var(--slide-offset); }
 to { translate: 0; }
}

@keyframes slide-y {
 from { transform: translateY(var(--slide-y-offset, 10px)); }
 to { transform: translateY(0); }
}

::view-transition-old(.fade-out) {
 animation: var(--duration-exit) ease-in fade reverse;
}
::view-transition-new(.fade-in) {
 animation: var(--duration-enter) ease-out var(--duration-exit) both fade;
}

::view-transition-old(.slide-down) {
 animation:
 var(--duration-exit) ease-out both fade reverse,
 var(--duration-exit) ease-out both slide-y reverse;
}
::view-transition-new(.slide-up) {
 animation:
 var(--duration-enter) ease-in var(--duration-exit) both fade,
 var(--duration-move) ease-in both slide-y;
}

::view-transition-old(.nav-forward) {
 --slide-offset: -60px;
 animation:
 var(--duration-exit) ease-in both fade reverse,
 var(--duration-move) ease-in-out both slide reverse;
}
::view-transition-new(.nav-forward) {
 --slide-offset: 60px;
 animation:
 var(--duration-enter) ease-out var(--duration-exit) both fade,
 var(--duration-move) ease-in-out both slide;
}

::view-transition-old(.nav-back) {
 --slide-offset: 60px;
 animation:
 var(--duration-exit) ease-in both fade reverse,
 var(--duration-move) ease-in-out both slide reverse;
}
::view-transition-new(.nav-back) {
 --slide-offset: -60px;
 animation:
 var(--duration-enter) ease-out var(--duration-exit) both fade,
 var(--duration-move) ease-in-out both slide;
}

::view-transition-group(.morph) {
 animation-duration: var(--duration-move);
}
::view-transition-image-pair(.morph) {
 animation-name: via-blur;
}
@keyframes via-blur {
 30% { filter: blur(3px); }
}

::view-transition-group(site-header),
::view-transition-group(gallery-controls),
::view-transition-group(gallery-back-link),
::view-transition-group(gallery-nav-prev),
::view-transition-group(gallery-nav-next) {
 animation: none;
 z-index: 100;
}
::view-transition-old(site-header),
::view-transition-old(gallery-controls),
::view-transition-old(gallery-back-link),
::view-transition-old(gallery-nav-prev),
::view-transition-old(gallery-nav-next) {
 display: none;
}
::view-transition-new(site-header),
::view-transition-new(gallery-controls),
::view-transition-new(gallery-back-link),
::view-transition-new(gallery-nav-prev),
::view-transition-new(gallery-nav-next) {
 animation: none;
}

@media (prefers-reduced-motion: reduce) {
 ::view-transition-old(*),
 ::view-transition-new(*),
 ::view-transition-group(*) {
 animation-duration: 0s !important;
 animation-delay: 0s !important;
 }
}

