@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}

@keyframes slide {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

@keyframes slide-y {
  from {
    transform: translateY(var(--slide-y-offset, 10px));
  }
  to {
    transform: translateY(0);
  }
}

@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

